theorem problem_21
  (n : ℕ) :
  let Ω : Finset (Fin (2 * n) → Bool) :=
    Finset.univ.filter (fun f => (Finset.univ.filter (fun i => f i = true)).card = n)
  let expected_score : ℝ := (∑ f in Ω, ∑ i : Fin (2 * n),
    let past := Finset.filter (fun j : Fin (2 * n) => j < i) Finset.univ
    let rem_red := n - (past.filter (fun j => f j = true)).card
    let rem_black := n - (past.filter (fun j => f j = false)).card
    if rem_red > rem_black then (if f i = true then (1 : ℝ) else 0)
    else if rem_black > rem_red then (if f i = false then (1 : ℝ) else 0)
    else 0.5) / Ω.card
  expected_score = n + 0.5 * ((4^n : ℝ) / (Nat.choose (2 * n) n : ℝ) - 1) := by
  sorry

problem:
Let $A=\begin{pmatrix}
2  & 1\\
1  & 3
\end{pmatrix}$. Prove that 
\begin{align*}
\max_{x \neq 0} \|Ax\|_2=\frac{5+\sqrt{5}}{2}.
\end{align*}

Let $f(x)=\sqrt{x^2+1}$. Prove that
\begin{align*}
\sup_{x \neq y}\frac{\|f(x)-f(y)\|}{\|x-y\|}=1.
\end{align*}

transformed_problem:
Let $f(x)=\sqrt{x^2+1}$. Prove that
\begin{align*}
\|f(x)-f(y)\| \leq \|x-y\| \quad \forall x,y.
\end{align*}
and for any $0<\alpha<1$ there exists $x_0,y_0$ such that
\begin{align*}
\|f(x)-f(y)\| > \alpha\|x-y\|.
\end{align*}

problem:
Let $S=\{(0,0),(2,0),(0,1)\}$. Prove that 
\begin{align*}
\left\{\lambda_1(0,0)+\lambda_2(2,0)+\lambda_3(0,1):\lambda_1,\lambda_2,\lambda_3 \geq 0, \lambda_1+\lambda_2+\lambda_3=1\right\}=\left\{(x,y)\in \mathbb{R}^2:x\geq0,y\geq0,\frac{x}{2}+y \leq 1\right\}.
\end{align*}

transformed_problem:
Let $S=\{(0,0),(2,0),(0,1)\}$. Prove that the smallest convex set containing $S$ is
\begin{align*}
\left\{(x,y)\in \mathbb{R}^2:x\geq0,y\geq0,\frac{x}{2}+y \leq 1\right\}.
\end{align*}

